// V1 prototype terminal: safe sandboxed workspace inspection and advisory AI.
const terminalCommands=['help','pwd','ls','tree','projects','cat <file>','validate','clear'];
function terminalWrite(text,kind='output'){
  const line=document.createElement('div');
  line.className='terminal-line '+kind;
  line.textContent=text;
  $('#terminalOutput').append(line);
  $('#terminalOutput').scrollTop=$('#terminalOutput').scrollHeight;
}
function terminalFiles(){return state.current?.files||[]}
function runTerminal(command){
  const input=command.trim();
  if(!input)return;
  terminalWrite('$ '+input,'command');
  const [verb,...args]=input.split(/\s+/);
  const arg=args.join(' ');
  if(verb==='clear'){ $('#terminalOutput').innerHTML=''; return }
  if(verb==='help'){ terminalWrite('Available commands: '+terminalCommands.join('  ·  ')); terminalWrite('Read-only sandbox. apt, pip, python, shell scripts, and arbitrary execution are not available.'); return }
  if(verb==='pwd'){ terminalWrite('/storage/emulated/0/Download/GummyBears'); return }
  if(verb==='uname'){ terminalWrite('Blocksmith web workspace · terminal simulator (not Linux)'); return }
  if(verb==='ls'||verb==='tree'){
    const files=terminalFiles();
    if(!files.length){ terminalWrite('Workspace is ready. Generate or open a project to see its pack files.'); return }
    if(verb==='ls') files.forEach(f=>terminalWrite(f.path));
    else { terminalWrite(state.current.name+'/'); files.forEach(f=>terminalWrite('  ├─ '+f.path)) }
    return;
  }
  if(verb==='projects'){ terminalWrite(state.projects.length?state.projects.map((p,i)=>`${i+1}. ${p.name} (${p.files?.length||0} files)`).join('\n'):'No saved projects yet. Generate an add-on first.'); return }
  if(verb==='cat'){
    const path=arg.replace(/^\.\//,'');
    if(!path||path.includes('..')||path.startsWith('/')){ terminalWrite('Usage: cat <workspace-relative-file>','error'); return }
    const file=terminalFiles().find(f=>f.path===path);
    if(!file){ terminalWrite(`File not found in the active project: ${path}`,'error'); return }
    terminalWrite(file.content); return
  }
  if(verb==='validate'){
    const files=terminalFiles();
    if(!files.length){ terminalWrite('No active project. Generate or open a project first.'); return }
    let errors=0;
    files.filter(f=>f.path.toLowerCase().endsWith('.json')).forEach(f=>{ try{ JSON.parse(f.content); terminalWrite(`✓ valid JSON  ${f.path}`) } catch(e){ errors++; terminalWrite(`× invalid JSON  ${f.path}: ${e.message}`,'error') } });
    terminalWrite(errors?`Validation finished with ${errors} JSON error(s).`:'JSON syntax check passed. Use Pack validator for manifest checks.');
    return;
  }
  if(['apt','apt-get','pip','pip3','python','python3','proot','debian','bash','sh','sudo','curl','wget','rm','mv','cp','chmod','node'].includes(verb)){
    terminalWrite(`${verb}: unavailable in the V1 browser sandbox. No system commands or packages are executed.`,'error');
    return;
  }
  terminalWrite(`Command not found: ${verb}. Type help for the supported read-only commands.`,'error');
}
